package com.zivwa.agristore.api;
import org.springframework.boot.autoconfigure.condition.ConditionalOnExpression;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.core.Authentication;
import org.springframework.http.*;
import org.springframework.web.server.ResponseStatusException;
import java.time.Instant;
import java.util.*;

@RestController
@RequestMapping("/api/v1")
@ConditionalOnExpression("'${app.auth-mode:local}' == 'local' or '${app.auth-mode:local}' == 'firebase-commerce'")
public class LocalCommerceController {
 private final LocalStore s; private final boolean testPayments;
 public LocalCommerceController(LocalStore s,@Value("${app.test-payments:false}") boolean testPayments){this.s=s;this.testPayments=testPayments;}
 private String uid(Authentication a){return a.getName();}
 private String id(){return UUID.randomUUID().toString();}
 private int number(Object v){try{return Integer.parseInt(String.valueOf(v));}catch(Exception e){throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Integer required");}}
 private Map<String,Object> notFound(Object value){if(value==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Record not found");return s.obj(value);}
 @PostMapping("/auth/register") public Map<String,Object> register(@RequestBody Map<String,Object> input){return s.register(input);}
 @PostMapping("/auth/login") public Map<String,Object> login(@RequestBody Map<String,Object> input){return s.login(input);}
 @PostMapping("/auth/logout") public Map<String,Object> logout(@RequestHeader("Authorization") String token){s.logout(token.substring(7));return Map.of("ok",true);}
 @GetMapping("/auth/me") public Map<String,Object> me(Authentication a){return s.profile(uid(a));}
 @GetMapping("/profile") public Map<String,Object> profile(Authentication a){return s.profile(uid(a));}
 @PutMapping("/profile") public Map<String,Object> profile(@RequestBody Map<String,Object> input,Authentication a){synchronized(s){var user=s.obj(s.map("users").get(uid(a)));for(String key:List.of("name","phone"))if(input.containsKey(key)){String value=s.text(input,key);s.require(value.length()<=120,"Profile value too long");user.put(key,value);}s.save();return s.profile(uid(a));}}
 @GetMapping("/store") public Map<String,Object> store(){return Map.of("settings",s.map("settings"),"testPayments",testPayments);}
 private Map<String,Object> quantities(String uid){return s.obj(s.map("carts").computeIfAbsent(uid,k->new LinkedHashMap<String,Object>()));}
 private Map<String,Object> cartFor(String uid){List<Map<String,Object>> rows=new ArrayList<>();long total=0;for(var e:quantities(uid).entrySet()){Models.Product p;try{p=s.catalog.detail(e.getKey(),true);}catch(ResponseStatusException ex){continue;}int q=number(e.getValue());long line=p.pricePaise()*q;total+=line;rows.add(Map.of("product",p,"quantity",q,"lineTotalPaise",line));}return Map.of("items",rows,"totalPaise",total);}
 @GetMapping("/cart") public Map<String,Object> cart(Authentication a){synchronized(s){return cartFor(uid(a));}}
 @PutMapping("/cart/items") public Map<String,Object> cart(@RequestBody Map<String,Object> input,Authentication a){synchronized(s){String pid=s.text(input,"productId");int q=number(input.get("quantity"));s.require(q>=0&&q<=99,"Quantity must be 0 to 99");var rows=quantities(uid(a));if(q==0)rows.remove(pid);else{var product=s.catalog.detail(pid,false);if(q>product.availableStock())throw new ResponseStatusException(HttpStatus.CONFLICT,"Insufficient stock");s.require(rows.size()<50||rows.containsKey(pid),"Cart limit reached");rows.put(pid,q);}s.save();return cartFor(uid(a));}}
 private Map<String,Object> addressRows(String uid){return s.obj(s.map("addresses").computeIfAbsent(uid,k->new LinkedHashMap<String,Object>()));}
 @GetMapping("/addresses") public Collection<Object> addresses(Authentication a){synchronized(s){return new ArrayList<>(addressRows(uid(a)).values());}}
 private Map<String,Object> saveAddress(String id,Map<String,Object> input,String uid){var rows=addressRows(uid);if(id!=null)notFound(rows.get(id));else id=id();var out=new LinkedHashMap<String,Object>();for(String key:List.of("name","line1","city","state","postalCode","phone")){String value=s.text(input,key);s.require(!value.isBlank()&&value.length()<=250,"Valid "+key+" required");out.put(key,value);}s.require(s.text(out,"postalCode").matches("[1-9][0-9]{5}"),"Invalid postal code");s.require(s.text(out,"phone").matches("[6-9][0-9]{9}"),"Invalid phone");out.put("id",id);rows.put(id,out);s.save();return out;}
 @PostMapping("/addresses") public Map<String,Object> address(@RequestBody Map<String,Object> input,Authentication a){synchronized(s){return saveAddress(null,input,uid(a));}}
 @PutMapping("/addresses/{id}") public Map<String,Object> address(@PathVariable String id,@RequestBody Map<String,Object> input,Authentication a){synchronized(s){return saveAddress(id,input,uid(a));}}
 @DeleteMapping("/addresses/{id}") public ResponseEntity<Void> deleteAddress(@PathVariable String id,Authentication a){synchronized(s){notFound(addressRows(uid(a)).remove(id));s.save();return ResponseEntity.noContent().build();}}
 @GetMapping("/orders") public List<Map<String,Object>> orders(Authentication a){synchronized(s){return s.map("orders").values().stream().map(s::obj).filter(o->uid(a).equals(o.get("customerId"))).toList();}}
 private Map<String,Object> order(String id,Authentication a){var o=notFound(s.map("orders").get(id));if(!uid(a).equals(o.get("customerId")))throw new ResponseStatusException(HttpStatus.NOT_FOUND);return o;}
 @GetMapping("/orders/{id}") public Map<String,Object> orderDetail(@PathVariable String id,Authentication a){synchronized(s){return order(id,a);}}
 @PostMapping("/orders") public Map<String,Object> checkout(@RequestBody Map<String,Object> input,@RequestHeader("Idempotency-Key") String key,Authentication a){synchronized(s){s.require(!key.isBlank()&&key.length()<=100,"Invalid checkout key");String dedupe=uid(a)+":"+key;if(s.map("checkoutKeys").containsKey(dedupe))return order(String.valueOf(s.map("checkoutKeys").get(dedupe)),a);var address=notFound(addressRows(uid(a)).get(s.text(input,"addressId")));String method=s.text(input,"paymentMethod");s.require(method.equals("COD")||(testPayments&&method.equals("TEST")),"Only COD is enabled; online payments require an integration");var quantities=quantities(uid(a));s.require(!quantities.isEmpty(),"Cart is empty");List<Map<String,Object>> items=new ArrayList<>();long total=0;for(var e:quantities.entrySet()){var p=s.catalog.detail(e.getKey(),false);int q=number(e.getValue());if(q>p.availableStock())throw new ResponseStatusException(HttpStatus.CONFLICT,"Insufficient stock for "+p.name());total+=q*p.pricePaise();items.add(Map.of("productId",p.id(),"name",p.name(),"sku",p.sku(),"quantity",q,"unitPricePaise",p.pricePaise()));}for(var e:quantities.entrySet()){var p=s.catalog.detail(e.getKey(),false);s.catalog.updateStock(p.id(),p.availableStock()-number(e.getValue()));}var o=new LinkedHashMap<String,Object>();String oid=id();o.put("id",oid);o.put("customerId",uid(a));o.put("items",items);o.put("address",new LinkedHashMap<>(address));o.put("totalPaise",total);o.put("status",method.equals("COD")?"PLACED":"PAYMENT_PENDING");o.put("paymentStatus",method.equals("COD")?"COD_PENDING":"PENDING");o.put("paymentMethod",method);o.put("createdAt",Instant.now().toString());s.map("orders").put(oid,o);s.map("checkoutKeys").put(dedupe,oid);quantities.clear();s.save();return o;}}
 @PostMapping("/orders/{id}/test-payment") public Map<String,Object> testPayment(@PathVariable String id,@RequestBody Map<String,Object> input,Authentication a){synchronized(s){if(!testPayments)throw new ResponseStatusException(HttpStatus.NOT_FOUND);var o=order(id,a);s.require("PAYMENT_PENDING".equals(o.get("status")),"Order is not pending payment");if(Boolean.TRUE.equals(input.get("success"))){o.put("paymentStatus","PAID");o.put("status","PLACED");}else{o.put("paymentStatus","FAILED");cancelStock(o);o.put("status","CANCELLED");}s.save();return o;}}
 @SuppressWarnings("unchecked") private void cancelStock(Map<String,Object> o){if("CANCELLED".equals(o.get("status")))return;for(Object line:(List<Object>)o.get("items")){var row=s.obj(line);var p=s.catalog.detail(s.text(row,"productId"),true);s.catalog.updateStock(p.id(),p.availableStock()+number(row.get("quantity")));}}
 @PostMapping("/contact") public Map<String,Object> contact(@RequestBody Map<String,Object> input){synchronized(s){s.require(!s.text(input,"email").isBlank()&&!s.text(input,"message").isBlank(),"Email and message required");s.require(s.text(input,"message").length()<=5000,"Message too long");var msg=new LinkedHashMap<>(input);msg.put("id",id());msg.put("createdAt",Instant.now().toString());s.map("contacts").put(s.text(msg,"id"),msg);s.save();return Map.of("ok",true);}}
 @GetMapping("/admin/products") public List<Models.Product> adminProducts(){return s.catalog.products(true);}
 @PostMapping("/admin/products") public Models.Product createProduct(@RequestBody Models.Product p){return saveProduct(null,p);}
 @PutMapping("/admin/products/{id}") public Models.Product updateProduct(@PathVariable String id,@RequestBody Models.Product p){s.catalog.detail(id,true);return saveProduct(id,p);}
 private Models.Product saveProduct(String id,Models.Product p){synchronized(s){s.require(p.availableStock()>=0,"Stock cannot be negative");var out=s.catalog.saveProduct(id,p);out=s.catalog.updateStock(out.id(),p.availableStock());s.save();return out;}}
 @DeleteMapping("/admin/products/{id}") public ResponseEntity<Void> archive(@PathVariable String id){synchronized(s){s.catalog.deactivate(id);s.save();return ResponseEntity.noContent().build();}}
 @GetMapping("/admin/categories") public List<Models.Category> adminCategories(){return s.catalog.categories(true);}
 @PostMapping("/admin/categories") public Models.Category category(@RequestBody Models.Category c){return category(null,c);}
 @PutMapping("/admin/categories/{id}") public Models.Category category(@PathVariable String id,@RequestBody Models.Category c){synchronized(s){var result=s.catalog.saveCategory(id,c);s.save();return result;}}
 @DeleteMapping("/admin/categories/{id}") public ResponseEntity<Void> deleteCategory(@PathVariable String id){synchronized(s){s.catalog.deleteCategory(id);s.save();return ResponseEntity.noContent().build();}}
 @GetMapping("/admin/orders") public Collection<Object> allOrders(){return new ArrayList<>(s.map("orders").values());}
 @PatchMapping("/admin/orders/{id}/status") public Map<String,Object> status(@PathVariable String id,@RequestBody Map<String,Object> input){synchronized(s){var o=notFound(s.map("orders").get(id));String next=s.text(input,"status"),old=s.text(o,"status");Map<String,List<String>> allowed=Map.of("PLACED",List.of("CONFIRMED","PROCESSING","CANCELLED"),"CONFIRMED",List.of("PROCESSING","SHIPPED","CANCELLED"),"PROCESSING",List.of("SHIPPED","CANCELLED"),"SHIPPED",List.of("DELIVERED"),"PAYMENT_PENDING",List.of("CANCELLED"));s.require(next.equals(old)||allowed.getOrDefault(old,List.of()).contains(next),"Invalid order status transition");if(next.equals("CANCELLED")&&!old.equals(next)){s.require(!"PAID".equals(o.get("paymentStatus")),"Paid order requires a refund integration before cancellation");cancelStock(o);}o.put("status",next);if(next.equals("DELIVERED")&&"COD".equals(o.get("paymentMethod")))o.put("paymentStatus","PAID");s.save();return o;}}
 @GetMapping("/admin/customers") public List<Map<String,Object>> customers(){return s.users().stream().map(u->s.profile(s.text(u,"id"))).toList();}
 @PatchMapping("/admin/customers/{id}") public Map<String,Object> customer(@PathVariable String id,@RequestBody Map<String,Object> input,Authentication a){synchronized(s){var u=notFound(s.map("users").get(id));s.require(!id.equals(uid(a)),"Cannot disable your own account");s.require(!"ADMIN".equals(u.get("role")),"Administrator status changes are not supported here");s.require(input.get("enabled") instanceof Boolean,"enabled must be boolean");u.put("enabled",input.get("enabled"));s.save();return s.profile(id);}}
 @GetMapping("/admin/settings") public Map<String,Object> settings(){return s.map("settings");}
 @PutMapping("/admin/settings") public Map<String,Object> settings(@RequestBody Map<String,Object> input){synchronized(s){for(String k:List.of("storeName","contactEmail","supportPhone")){String v=s.text(input,k);s.require(v.length()<255,"Setting too long");s.map("settings").put(k,v);}s.save();return s.map("settings");}}
 @GetMapping("/admin/contacts") public Collection<Object> contacts(){return new ArrayList<>(s.map("contacts").values());}
 @GetMapping("/admin/reports") public Map<String,Object> reports(){synchronized(s){Map<String,Integer> counts=new LinkedHashMap<>();long collected=0;for(Object value:s.map("orders").values()){var o=s.obj(value);counts.merge(s.text(o,"status"),1,Integer::sum);if("PAID".equals(o.get("paymentStatus")))collected+=((Number)o.get("totalPaise")).longValue();}return Map.of("orders",s.map("orders").size(),"customers",s.map("users").size(),"products",s.catalog.products(true).size(),"collectedPaise",collected,"ordersByStatus",counts,"lowStock",s.catalog.products(true).stream().filter(p->p.availableStock()<10).toList());}}
}
